insert into public.site_settings(brand_name,tagline,location,phone,whatsapp_message,hero_heading,hero_text,about_heading,about_content,terms) values ('Chai Rides','Ride to Sip','Siddipet, Telangana, India','+91 6302567570','Hello Chai Rides Team, I am interested in exploring a Chai Rides franchise opportunity. Could you please share the franchise investment details, available packages, setup requirements, and application process? I would appreciate your guidance. Thank you.','Build your next chapter with Chai Rides.','A premium, modern Indian tea franchise rooted in Siddipet, Telangana.','A focused franchise, built around chai.','Chai Rides combines a recognisable tea-and-snacks format with training, operational guidance and marketing support.','Package inclusions and promotional raw-material values are subject to written terms, availability and final confirmation. Promotional statements are not guarantees of revenue, returns or success.') on conflict do nothing;
insert into public.franchise_packages(name,slug,investment_amount,description,promotional_offer,terms,sort_order) values
('Classic Franchise','classic-franchise',120000,'A focused Chai Rides setup with branding, furniture, equipment, initial raw materials, training and marketing support.','Promotional raw materials described as capable of supporting ₹1.3 lakh in revenue are included subject to terms; this is not guaranteed earnings.','Final dimensions, site requirements and unclear poster wording require admin confirmation.',10),
('Special Offer Franchise','special-offer-franchise',150000,'An expanded Chai Rides setup with additional equipment, branding and a broader initial raw-material selection.','Promotional raw materials described as capable of supporting ₹1.4 lakh in revenue are included subject to terms; this is not guaranteed earnings.','“100% success” is poster wording only and is not a guaranteed outcome. Final inclusions are subject to written agreement.',20) on conflict(slug) do update set investment_amount=excluded.investment_amount,description=excluded.description,promotional_offer=excluded.promotional_offer,terms=excluded.terms;
insert into public.franchise_benefits(package_id,benefit_type,title,description,sort_order) select p.id,v.t,v.title,v.d,v.o from public.franchise_packages p join (values
('classic-franchise','general','No royalty','No ongoing royalty listed in the supplied promotion.',10),('classic-franchise','general','No monthly fees','No monthly franchise fee listed.',20),('classic-franchise','general','Lifetime agreement','Subject to final written agreement.',30),('classic-franchise','training','3 days of free training','Recipe mastery, operations, customer service and business management.',40),('classic-franchise','marketing','Social media marketing support','Page setup, branding, content strategy, regular posts and engagement support.',50),
('special-offer-franchise','general','No royalty','No ongoing royalty listed in the supplied promotion.',10),('special-offer-franchise','general','One-time settlement','Subject to final written agreement.',20),('special-offer-franchise','general','Lifetime agreement','Subject to final written agreement.',30),('special-offer-franchise','training','3 days of free training','Training included as stated in the supplied promotion.',40),('special-offer-franchise','marketing','Social media marketing support','Marketing support included as stated in the supplied promotion.',50)
) v(slug,t,title,d,o) on p.slug=v.slug;
insert into public.franchise_faqs(question,answer,sort_order) values ('Are returns guaranteed?','No. Promotional phrases such as “high returns” or raw-material revenue values are not guaranteed earnings. Results depend on location, operations, demand and other factors.',10),('Are there royalty or monthly fees?','The supplied promotional information states no royalty and no monthly fees for the Classic package, and no royalty for the Special Offer package. Final terms must be confirmed in the written agreement.',20),('How do I start?','Submit the application form or contact the Chai Rides team by phone or WhatsApp. The team will review location, package fit and setup requirements.',30),('Can package contents change?','Yes. Availability, dimensions, quantities and unclear poster wording are subject to admin confirmation and the final agreement.',40);
